//! BQ044's command-invoked core, retaining the original paid command frame.
use crate::{engine::RuleResult,model::*,rules::*};
use serde::{Serialize,Deserialize};
#[derive(Clone,Debug,Serialize,Deserialize)]
#[serde(deny_unknown_fields)]
pub struct State{pub core:Box<SourceSnapshot>,pub phase:Phase}
#[derive(Clone,Debug,Serialize,Deserialize)]
pub enum Phase{Sacrifice,After{victim:Box<SourceSnapshot>},Opponent{victim:Box<SourceSnapshot>},Repress{victim:Box<SourceSnapshot>,seat:usize,regions:Vec<(usize,String,u32)>}}
fn same<T:Serialize>(a:&T,b:&T)->bool{serde_json::to_value(a).unwrap()==serde_json::to_value(b).unwrap()}
impl Game{
 pub(crate) fn bq044_core_parent(&self,f:&ResolutionFrame)->RuleResult<()>{match f.source.card.definition.as_str(){"BQ048"=>{self.validate_bq048_frame(f)?;if f.cursor!=1||!matches!(f.steps[0].op,Op::BQ048InvokeCore){return Err("BQ044核心须由原命令发动".into())}},"BQ063"=>{self.validate_bq063_frame(f)?;if !matches!(f.cursor,1|2)||!matches!(f.steps[f.cursor-1].op,Op::BQ063InvokeCore){return Err("BQ044核心发动序号损坏".into())}},_=>return Err("BQ044核心没有直接免费发动入口".into())}Ok(())}
 pub(crate) fn bq044_core_state(&self,f:&ResolutionFrame,s:&State)->RuleResult<()>{self.bq044_core_parent(f)?;let c=&s.core.card;if c.definition!="BQ044"||c.owner!=f.actor||c.controller!=f.actor||c.face_down||!self.mystic_instance_valid(&c.id)||!self.core_zones.iter().any(|z|z.owner==f.actor&&z.definition==c.definition)||s.core.region.is_some_and(|r|r>=self.regions.len())||s.core.region.is_some()!=s.core.source_region_instance.is_some()||s.core.source_region_instance.as_deref().is_some_and(|id|!self.mystic_instance_valid(id))||s.core.play_source.is_some()||s.core.attachment_host_instance.is_some()||s.core.death_echo.is_some()||s.core.observed_death.is_some()||s.core.observed_exposure.is_some()||s.core.observed_mobility_grant.is_some(){return Err("BQ044核心原身份损坏".into())}self.mobility_immutable_identity(c)?;
 if let Phase::Sacrifice=s.phase{if !same(s.core.as_ref(),&self.selected_core_source(f.actor)?){return Err("BQ044牺牲前所选核心已变化".into())}}else{let victim=match &s.phase{Phase::After{victim}|Phase::Opponent{victim}|Phase::Repress{victim,..}=>victim,_=>unreachable!()};let c=&victim.card;if c.controller!=f.actor||c.owner>=self.players.len()||c.face_down||!crate::catalog::catalog().cards.iter().any(|d|d.id==c.definition&&d.kind=="character")||!self.mystic_instance_valid(&c.id)||self.in_play(&c.id).is_some()||victim.region.is_none_or(|r|r>=self.regions.len())||victim.source_region_instance.as_deref().is_none_or(|id|!self.mystic_instance_valid(id))||victim.play_source.is_some()||victim.attachment_host_instance.is_some()||victim.death_echo.is_some()||victim.observed_death.is_some()||victim.observed_exposure.is_some()||victim.observed_mobility_grant.is_some(){return Err("BQ044核心缺原实际牺牲角色".into())}self.mobility_immutable_identity(c)?;}Ok(())}
 fn bq044_core_options(&self,f:&ResolutionFrame,s:&State)->RuleResult<(usize,&'static str,&'static str,Option<u32>,Vec<ChoiceOption>)>{self.bq044_core_state(f,s)?;Ok(match &s.phase{Phase::Sacrifice=>(f.actor,"bq044-core-sacrifice","核心：牺牲一个本方角色",None,self.regions.iter().enumerate().filter(|(_,r)|!r.vacant).flat_map(|(r,v)|v.cards.iter().map(move|c|(r,c))).filter(|(_,c)|c.controller==f.actor&&!c.face_down&&crate::catalog::card(&c.definition).kind=="character").map(|(r,c)|self.option(c,f.actor,Some(r),None)).collect()),Phase::Opponent{..}=>(f.actor,"bq044-core-opponent","核心：选择遏制的敌方玩家",None,self.players.iter().filter(|p|!p.eliminated&&self.team(p.seat)!=self.team(f.actor)).map(|p|ChoiceOption{id:player_id(p.seat),label:p.name.clone(),card:None}).collect()),Phase::Repress{seat,regions,..}=>{if *seat>=self.players.len()||self.team(*seat)==self.team(f.actor)||regions.is_empty()||!same(regions,&self.batch20_repress_regions(*seat)){return Err("BQ044核心遏制地区变化".into())}(*seat,"bq044-core-repress","核心：移除1个本方势力",Some(1),self.batch20_repress_options(regions,1))},Phase::After{..}=>return Err("BQ044离场等待不能冒充玩家选择".into())})}
 fn bq044_core_offer(&mut self,f:ResolutionFrame,s:State)->RuleResult<()>{let(seat,kind,title,amount,options)=self.bq044_core_options(&f,&s)?;if options.is_empty(){self.effects.push_front(Effect::Frame{frame:Box::new(f)});}else{self.choice(seat,kind,title.into(),options,1,1,amount,ChoiceResolution::Frame{frame:Box::new(f),choice:FrameChoice::BQ044Core(s)});}Ok(())}
 pub(crate) fn bq044_core_start(&mut self,f:ResolutionFrame)->RuleResult<()>{let core=Box::new(self.selected_core_source(f.actor)?);self.bq044_core_offer(f,State{core,phase:Phase::Sacrifice})}
 pub(crate) fn bq044_core_after(&mut self,f:ResolutionFrame,mut s:State)->RuleResult<()>{self.bq044_core_state(&f,&s)?;let Phase::After{victim}=s.phase else{return Err("BQ044核心抽牌只能在原牺牲之后".into())};if self.death_replacements.iter().any(|d|d.source.card.id==victim.card.id||d.blood.as_ref().is_some_and(|b|b.host.card.id==victim.card.id))||self.effects.iter().any(|e|matches!(e,Effect::CoreReturn{departure}if departure.source.card.id==victim.card.id)){return Err("BQ044核心不能越过未决离场".into())}if self.players[f.actor].eliminated{return Ok(())}self.draw(f.actor,1)?;if self.players[f.actor].eliminated{return Ok(())}s.phase=Phase::Opponent{victim};self.bq044_core_offer(f,s)}
 pub(crate) fn bq044_core_choose(&mut self,f:ResolutionFrame,mut s:State,chooser:usize,a:&Action,ids:&[String])->RuleResult<()>{let(seat,_,_,_,options)=self.bq044_core_options(&f,&s)?;if chooser!=seat||*a!=(Action{choice_id:a.choice_id.clone(),selected:a.selected.clone(),..Action::new("choose")})||ids.len()!=1||!options.iter().any(|o|o.id==ids[0]){return Err("BQ044核心选择不合法".into())}match s.phase{Phase::Sacrifice=>{let(r,c)=self.board(&ids[0]).ok_or("核心牺牲对象离场")?;let mut victim=self.source_snapshot(c,Some(r));victim.source_region_instance=Some(self.regions[r].card.id.clone());s.phase=Phase::After{victim:Box::new(victim)};let before=self.death_instances();let tail=std::mem::take(&mut self.effects);self.remove_dead(&ids[0],RemovalCause::Sacrifice);if !self.defer_death_caller(f.clone(),crate::death_continuation::DeathCallerKind::BQ044Core{state:s.clone()},&before){self.effects.push_back(Effect::BQ044CoreResume{frame:Box::new(f),state:s});}self.effects.extend(tail);Ok(())},Phase::Opponent{victim}=>{let seat=ids[0][1..].parse::<usize>().map_err(|_|"敌方席位无效")?;let regions=self.batch20_repress_regions(seat);if regions.is_empty(){self.effects.push_front(Effect::Frame{frame:Box::new(f)});Ok(())}else{s.phase=Phase::Repress{victim,seat,regions};self.bq044_core_offer(f,s)}},Phase::Repress{seat,regions,..}=>{self.wm040_repress_complete(seat,&regions,ids)?;self.effects.push_front(Effect::Frame{frame:Box::new(f)});Ok(())},Phase::After{..}=>Err("离场等待不是选择".into())}}
 pub(crate) fn validate_bq044_core_state(&self)->RuleResult<()>{let mut ids=std::collections::BTreeSet::new();for e in &self.effects{match e{Effect::BQ044CoreResume{frame,state}=>{self.bq044_core_state(frame,state)?;if !matches!(state.phase,Phase::After{..})||!ids.insert(frame.frame_id.clone()){return Err("BQ044核心续体阶段或唯一性损坏".into())}},Effect::DeathCaller{caller}=>if let crate::death_continuation::DeathCallerKind::BQ044Core{state}=&caller.kind{self.bq044_core_state(&caller.frame,state)?;if !matches!(state.phase,Phase::After{..})||!ids.insert(caller.frame.frame_id.clone()){return Err("BQ044核心死亡续体重复".into())}},_=>()}}
 if let Some(p)=&self.pending{if let ChoiceResolution::Frame{frame,choice:FrameChoice::BQ044Core(s)}=&p.resolution{let(seat,kind,title,amount,options)=self.bq044_core_options(frame,s)?;if !ids.insert(frame.frame_id.clone())||options.is_empty()||p.seat!=seat||p.choice.player_id!=player_id(seat)||p.choice.kind!=kind||p.choice.title!=title||p.choice.amount!=amount||p.choice.min!=Some(1)||p.choice.max!=Some(1)||p.choice.allow_decline!=Some(false)||!p.choice.preview_cards.is_empty()||!self.mystic_instance_valid(&p.choice.id)||!same(&p.choice.options,&options){return Err("BQ044核心待选或排他续体损坏".into())}}}if self.stack.iter().any(|i|ids.contains(&i.id))||self.effects.iter().any(|e|matches!(e,Effect::Frame{frame}if ids.contains(&frame.frame_id))){return Err("BQ044核心原命令不能并存重复载体".into())}Ok(())}
}
